CREATE DATABASE IF NOT EXISTS jejaksehat;
USE jejaksehat;

CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY, nama VARCHAR(100) NOT NULL, email VARCHAR(100) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('PASIEN','ADMIN') NOT NULL DEFAULT 'PASIEN', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE refresh_tokens (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, token_hash VARCHAR(255) NOT NULL, expires_at DATETIME NOT NULL, revoked BOOLEAN NOT NULL DEFAULT FALSE, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE anggota_keluarga (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, nama_lengkap VARCHAR(100) NOT NULL, hubungan VARCHAR(30) NOT NULL, tanggal_lahir DATE NULL, jenis_kelamin ENUM('L','P') NULL, golongan_darah VARCHAR(10) NULL, tinggi_cm SMALLINT NULL, berat_kg DECIMAL(5,2) NULL, catatan TEXT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE faskes (id INT AUTO_INCREMENT PRIMARY KEY, nama VARCHAR(150) NOT NULL, jenis VARCHAR(30) NOT NULL, alamat VARCHAR(255), kota VARCHAR(80), telepon VARCHAR(20), UNIQUE KEY nama_kota (nama, kota));
CREATE TABLE riwayat_kesehatan (id INT AUTO_INCREMENT PRIMARY KEY, anggota_id INT NOT NULL, kategori ENUM('PENYAKIT','ALERGI') NOT NULL, nama VARCHAR(100) NOT NULL, tanggal_mulai DATE NULL, status ENUM('AKTIF','TERKENDALI','SEMBUH') DEFAULT 'AKTIF', tingkat_keparahan VARCHAR(20), gejala_reaksi TEXT, catatan TEXT, FOREIGN KEY (anggota_id) REFERENCES anggota_keluarga(id) ON DELETE CASCADE);
CREATE TABLE kunjungan (id INT AUTO_INCREMENT PRIMARY KEY, anggota_id INT NOT NULL, faskes_id INT NOT NULL, riwayat_id INT NULL, tanggal_kunjungan DATE NOT NULL, nama_dokter VARCHAR(100), keluhan TEXT, diagnosis TEXT, tindakan_terapi TEXT, catatan TEXT, FOREIGN KEY (anggota_id) REFERENCES anggota_keluarga(id) ON DELETE CASCADE, FOREIGN KEY (faskes_id) REFERENCES faskes(id) ON DELETE RESTRICT, FOREIGN KEY (riwayat_id) REFERENCES riwayat_kesehatan(id) ON DELETE SET NULL);
CREATE TABLE dokumen_medis (id INT AUTO_INCREMENT PRIMARY KEY, kunjungan_id INT NOT NULL, judul VARCHAR(150) NOT NULL, jenis VARCHAR(30) NOT NULL, nama_berkas VARCHAR(255) NOT NULL, mime_type VARCHAR(50) NOT NULL, ukuran_kb INT NOT NULL, tanggal_dokumen DATE, catatan TEXT, FOREIGN KEY (kunjungan_id) REFERENCES kunjungan(id) ON DELETE CASCADE);
